Action: run_sql({'query': "SELECT e.gmap_id, e.name, e.address, e.avg_rating, e.num_of_reviews, e.price,\n       STRING_AGG(DISTINCT c.category, ', ') as categories\nFROM establishments e\nLEFT JOIN establishment_categories ec ON e.gmap_id = ec.gmap_id\nLEFT JOIN category c ON ec.category_id = c.category_id\nWHERE (e.address LIKE '%84116%' OR e.address LIKE '%Rose Park%')\n  AND ST_Y(e.geom) BETWEEN 40.768 AND 40.805\n  AND ST_X(e.geom) BETWEEN -111.95 AND -111.91\nGROUP BY e.gmap_id, e.name, e.address, e.avg_rating, e.num_of_reviews, e.price\nORDER BY e.avg_rating DESC, e.num_of_reviews DESC;"})

