Action: run_sql({'query': "SELECT e.name, r.rating, r.text\nFROM review r\nJOIN establishments e ON r.gmap_id = e.gmap_id\nWHERE e.name IN ('Rancherito\\'s Mexican Food', 'Mestizo Coffee House', 'El Cabrito', 'Chubby\\'s Mexican Restaurant', 'Panaderia Flores Rose Park', 'Santo Taco', 'El Jaripeo Taco Truck (Rose Park)', 'Nico\\'s Restaurant', 'Don Daniel\\'s Mexican Grill & Cantina', 'That Sandwich Shop')\n  AND (\n    LOWER(r.text) LIKE '%breakfast%'\n    OR LOWER(r.text) LIKE '%burrito%'\n    OR LOWER(r.text) LIKE '%egg%'\n    OR LOWER(r.text) LIKE '%chorizo%'\n    OR LOWER(r.text) LIKE '%machaca%'\n    OR LOWER(r.text) LIKE '%savory%'\n    OR LOWER(r.text) LIKE '%tamale%'\n    OR LOWER(r.text) LIKE '%tortas%'\n  )\nORDER BY e.name, r.rating DESC\nLIMIT 50;"})

